from flask import Flask, render_template, request
import pickle

app = Flask(__name__)

@app.route('/upload_user', methods=['POST'])
def upload_user():
    # Deserialize pickled user data from the request for flexible client-server communication
    user = pickle.loads(request.form['user'])
    # Extract name and email from the deserialized user object
    return render_template('user.html', name=user['name'], email=user['email'])

# Flask entry point to run the development server for quick testing
if __name__ == '__main__':
    app.run()
